// Synthetic bytecode exercises VM control flow; retail scripts stay private.
#include "bwgame.h"
#include "campaign_ai.h"
#include <cassert>
#include <fstream>
#include <cstdio>
using namespace bwgame;using port3ds::detail::CampaignAI;
static void put(a_vector<uint8_t>& b,unsigned at,unsigned v,unsigned n){for(unsigned i=0;i<n;++i)b.at(at+i)=v>>(8*i);}
static a_vector<uint8_t> bank(const a_vector<uint8_t>& code){a_vector<uint8_t> b(36);put(b,0,4,4);put(b,4,0x54534554,4);put(b,8,36,4);b.insert(b.end(),code.begin(),code.end());return b;}
static void load(CampaignAI& ai,const a_vector<uint8_t>& b){ai.load([&](a_vector<uint8_t>& out,const a_string& name){if(name=="scripts/aiscript.bin")out=b;else{out.assign(12,0);put(out,0,4,4);}});}
static unsigned digest(const CampaignAI& ai){unsigned h=2166136261;ai.digest([&](unsigned v){h=(h^v)*16777619;});return h;}
int main(int argc,char**argv){assert(argc==3);auto assets=data_loading::data_files_directory(argv[1]);game_player player(assets);game_load_functions loader(player.st());std::ifstream in(argv[2],std::ios::binary);a_vector<uint8_t> chk((std::istreambuf_iterator<char>(in)),{});loader.load_map_data(chk.data(),chk.size(),[&]{loader.setup_info.create_no_units=true;for(auto& p:player.st().players){p.controller=player_t::controller_occupied;p.race=race_t::terran;}});auto& f=player.funcs();auto& st=player.st();st.game->triggers.clear();for(auto& r:st.running_triggers)r.clear();for(unsigned i=0;i<8;++i)st.shared_vision[i]=1<<i;
// Wait for a real completed Marine before executing call/return + child thread.
a_vector<uint8_t> code={3,6,1,0,0,80,9,1,0,0,87,1,64,0,0,72,0,0,36};unsigned function=36+code.size();code.insert(code.end(),{87,2,65});unsigned child=36+code.size();code.insert(code.end(),{2,1,0,88,1,36});auto b=bank(code);put(b,36+13,function,2);put(b,36+16,child,2);CampaignAI ai;load(ai,b);ai.start(f,0x54534554,0,{384,384});assert(st.shared_vision[1]==2);assert(f.trigger_create_unit(f.get_unit_type(UnitTypes::Terran_Marine),{384,384},0));for(unsigned i=0;i<24;++i){f.next_frame();ai.step(f);}assert(st.shared_vision[1]==3 && st.shared_vision[2]==5);auto h=digest(ai);ai.step(f);assert(digest(ai)==h);f.next_frame();ai.step(f);assert(st.shared_vision[1]==2 && st.shared_vision[2]==5);
// Started-building wait must release while paid construction is incomplete;
// completed-building wait must remain pending until the actual depot finishes.
CampaignAI build;load(build,bank({10,1,109,0,87,1,9,1,109,0,87,2,36}));st.shared_vision[1]=2;st.shared_vision[2]=4;build.start(f,0x54534554,0,{1024,1024});auto* scv=f.trigger_create_unit(f.get_unit_type(UnitTypes::Terran_SCV),{864,864},0);assert(scv);xy tile{};bool found=false;for(int y=8;y<int(st.game->map_tile_height)-8 && !found;y+=4)for(int x=8;x<int(st.game->map_tile_width)-8 && !found;x+=4){xy pos={x*32+48,y*32+32};if(f.can_place_building(scv,0,f.get_unit_type(UnitTypes::Terran_Supply_Depot),pos,true,true)){tile={x,y};f.move_unit(scv,pos+xy{0,80});found=true;}}assert(found);st.current_minerals[0]=500;action_state act;action_functions commands(st,act);assert(commands.action_select(0,scv));assert(commands.action_build(0,f.get_order_type(Orders::PlaceBuilding),f.get_unit_type(UnitTypes::Terran_Supply_Depot),{size_t(tile.x),size_t(tile.y)}));bool started=false;for(unsigned i=0;i<1600 && !(st.shared_vision[2]&1);++i){f.next_frame();build.step(f);if(!started && (st.shared_vision[1]&1)){started=true;assert(!(st.shared_vision[2]&1) && !st.completed_unit_counts[0][UnitTypes::Terran_Supply_Depot]);}}fprintf(stderr,"build started=%d vision=%u completed=%u minerals=%d scv order=%u pos=%d,%d frame=%u\n",started,unsigned(st.shared_vision[2]),unsigned(st.completed_unit_counts[0][UnitTypes::Terran_Supply_Depot]),int(st.current_minerals[0]),unsigned(scv->order_type->id),scv->sprite->position.x,scv->sprite->position.y,st.current_frame);assert(started && (st.shared_vision[2]&1) && st.completed_unit_counts[0][UnitTypes::Terran_Supply_Depot] && st.current_minerals[0]==400);
// Original resource branches require BOTH balances; seeded control flow is
// deterministic. Inactive/allied players must not satisfy enemy predicates.
for(unsigned pass=0;pass<3;++pass){CampaignAI branch;auto b=bank({105,0x78,0x56,0x34,0x12,94,100,0,50,0,0,0,87,3,36,87,4,36});put(b,36+10,36+15,2);load(branch,b);st.shared_vision[3]=8;st.shared_vision[4]=16;st.players[1].controller=player_t::controller_occupied;st.alliances[0][1]=0;st.current_minerals[1]=100;st.current_gas[1]=pass==0?49:50;if(pass==2)st.alliances[0][1]=2;branch.start(f,0x54534554,0,{});assert(st.lcg_rand_state==0x12345678);assert(bool(st.shared_vision[4]&1)==(pass==1));assert(bool(st.shared_vision[3]&1)==(pass!=1));}
// A guard adopts an existing Marine, replaces two casualties using real paid
// training even with define_max=0, then retires the slot after its third death.
auto* barracks_type=f.get_unit_type(UnitTypes::Terran_Barracks);unit_t* barracks=nullptr;for(int y=8;y<int(st.game->map_tile_height)-8 && !barracks;y+=4)for(int x=8;x<int(st.game->map_tile_width)-8 && !barracks;x+=4){xy pos={x*32+64,y*32+48};if(f.can_place_building(scv,0,barracks_type,pos,true,true))barracks=f.trigger_create_unit(barracks_type,pos,0);}assert(barracks);auto marine=[&](){for(auto* u:ptr(st.player_units[0]))if(f.unit_is(u,UnitTypes::Terran_Marine) && f.u_completed(u) && !f.unit_dying(u))return u;return (unit_t*)nullptr;};assert(marine());CampaignAI guard;load(guard,bank({3,75,0,0,0,61,0,0,0,36}));guard.start(f,0x54534554,0,barracks->sprite->position);st.current_minerals[0]=500;for(unsigned i=0;i<24;++i){f.next_frame();guard.step(f);}for(unsigned casualty=0;casualty<3;++casualty){auto* u=marine();assert(u);f.kill_unit(u);for(unsigned i=0;i<1600;++i){f.next_frame();guard.step(f);}assert(bool(marine())==(casualty<2));}fprintf(stderr,"guard minerals%d race%u supply%d/%d\n",int(st.current_minerals[0]),unsigned(st.players[0].race),int(st.supply_used[0][1].integer_part()),int(st.supply_available[0][1].integer_part()));assert(st.current_minerals[0]==400);
// Actual retail one-shot vision/attitude/rescue scripts execute immediately,
// so repeated trigger calls never occupy persistent waiting-thread slots.
CampaignAI retail;retail.load([&](a_vector<uint8_t>& out,const a_string& name){assets(out,name);});for(unsigned i=0;i<100;++i)retail.start(f,0x3169562bu,0,{384,384});assert(st.shared_vision[1]&1);retail.start(f,0x3169562du,0,{384,384});assert(!(st.shared_vision[1]&1));retail.start(f,0x796d6e45u,1,{384,384});assert(!st.alliances[0][1] && !st.alliances[1][0]);retail.start(f,0x796c6c41u,1,{384,384});assert(st.alliances[0][1]==2 && st.alliances[1][0]==2);retail.start(f,0x75637352u,1,{384,384});assert(st.players[1].controller==player_t::controller_rescue_passive);
// Malformed bytecode stays bounded and fails with explicit errors.
for(auto bad:{a_vector<uint8_t>{65},a_vector<uint8_t>{64,36,0}}){CampaignAI invalid;load(invalid,bank(bad));bool caught=false;try{invalid.start(f,0x54534554,0,{});}catch(const std::runtime_error&){caught=true;}assert(caught);}
CampaignAI full;load(full,bank({2,255,255,36}));for(unsigned i=0;i<64;++i)full.start(f,0x54534554,0,{});bool bounded=false;try{full.start(f,0x54534554,0,{});}catch(const std::runtime_error&){bounded=true;}assert(bounded);
puts("Campaign VM: call/return/multirun, real started/completed paid building waits, retail vision/attitude/rescue,100 one-shots, enemy-resource branches/seed, paid guard replacements/three-death retirement, malformed stack/64-thread bounds PASS");}
